export const DEFAULT_ARTICLE_SLUG = "a1";
export const COMMENT_LOAD_ERROR = "Failed to load comments";
export const UNKNOWN_AUTHOR = "unknown";

export const API_ENDPOINTS = {
  articleComments: (slug) => `/api/articles/${encodeURIComponent(slug)}/comments`,
};

const { findCommentsByArticleSlug } = require("./commentsService");
const { API_ROUTES } = require("./config");
const { sendNotFound, sendServerError } = require("./httpResponses");

function registerRoutes(app) {
  app.get(API_ROUTES.articleComments, getArticleComments);
}

async function getArticleComments(req, res) {
  try {
    const { slug } = req.params;
    const comments = await findCommentsByArticleSlug(slug);
    if (!comments) {
      return sendNotFound(res);
    }

    res.json({ comments });
  } catch (error) {
    sendServerError(res, error);
  }
}

module.exports = { registerRoutes };

import { API_ENDPOINTS, COMMENT_LOAD_ERROR } from "./config";

async function requestJson(url, failureMessage, options = {}) {
  const res = await fetch(url, options);

  if (!res.ok) {
    throw new Error(`${failureMessage}: ${res.status}`);
  }

  return res.json();
}

export async function getComments(slug, options = {}) {
  const data = await requestJson(
    API_ENDPOINTS.articleComments(slug),
    COMMENT_LOAD_ERROR,
    options,
  );

  return data.comments;
}

